local BaseEffect = import('Game.Chapter.NewChapterEffect.BaseEffect')
local base = BaseEffect

local RotateRoleLight = CS.RotateRoleLight

local CameraCustomData = CS.CameraCustomData

local LayerMask = CS.UnityEngine.LayerMask

local KTool = CS.Engine.Lib.KTool

---@class CharacterTeleportEffect : BaseEffect
local CharacterTeleportEffect = Class("CharacterTeleportEffect", BaseEffect)

local NewChapterConstants = import("Game.Chapter.NewChapterConstants")

local layer2d = LayerMask.GetMask("2D")

local layerNormal = LayerMask.GetMask("role", "2D", "role_shadowcaster", "big_skill_role_shadowcaster", "ChapterRole")

function CharacterTeleportEffect:__init()
end

function CharacterTeleportEffect:__delete()
end

function CharacterTeleportEffect:Initialize(parameters)
    base.StartEffect(self, parameters)
    if parameters.effect ~= NewChapterConstants.CharacterEffect.PhoneCall then
        return
    end
end

---@param object table @{object = object, 
--                    camera = vo.Is2D and self.Camera2D or self.Camera3D,
--                    effectCamera = self.CameraEffect,
--                    effect = self.effect}
function CharacterTeleportEffect:StartEffect(object)
    base.StartEffect(self, object)
    --printInfo(object.name)
    
    local character = object.object.transform:Find(NewChapterConstants.CharacterName)
    if isNull(character) then
        return
    end
    --character.gameObject:SetActive(true)
    KTool.ChangeAllLayer(character.gameObject, NewChapterConstants.ChapterEffectLayer, NewChapterConstants.RoleLayer)
    KTool.ChangeAllLayer(character.gameObject, NewChapterConstants.ChapterEffectShadowLayer, NewChapterConstants.RoleShadow)
    local light = character.gameObject:GetComponent(typeof(RotateRoleLight))
    light:OpenCommunicationState()
    
    local effectCamera = object.effectCamera.gameObject:GetComponent(typeof(CameraCustomData))
    effectCamera.communicationSetting.communicationState = 1
    
    object.effect.gameObject:SetActive(true)
    --object.camera.cullingMask = layer2d
    effectCamera.gameObject:SetActive(true)
end

function CharacterTeleportEffect:IsFinish()
    base.IsFinish(self)
end

function CharacterTeleportEffect:EndEffect(object)
    base.EndEffect(self, object)
end

function CharacterTeleportEffect:RemoveEffect(object)
    base.RemoveEffect(self, object)
    local character = object.object.transform:Find(NewChapterConstants.CharacterName)
    if isNull(character) then
        return
    end
    --character.gameObject:SetActive(true)
    KTool.ChangeAllLayer(character.gameObject, NewChapterConstants.RoleLayer, NewChapterConstants.ChapterEffectLayer)
    KTool.ChangeAllLayer(character.gameObject, NewChapterConstants.RoleShadow, NewChapterConstants.ChapterEffectShadowLayer)
    local light = character.gameObject:GetComponent(typeof(RotateRoleLight))
    light:CloseCommunicationState()

    local effectCamera = object.effectCamera.gameObject:GetComponent(typeof(CameraCustomData))
    effectCamera.communicationSetting.communicationState = 0

    object.effect.gameObject:SetActive(false)
    --object.camera.cullingMask = layerNormal
    effectCamera.gameObject:SetActive(false)
end

return CharacterTeleportEffect